[{"type":"text","text":"<script setup>
import { ref, computed } from 'vue'
import { onShow, onLoad, onUnload } from '@dcloudio/uni-app'
import userStore from '@/store/user'
import { showToast } from '@/utils/ui'
import { appSuggestListVoByCertNumber, addAppSuggest } from '@/api/autonomy'
import { getMyHousesNew } from '@/api/property'
import ZsBottomPopup from '@/components/ZsBottomPopup/ZsBottomPopup.vue'

// 鍊¤璁鍒楄〃
const topicList = ref([])

// 宸查€夋嫨鐨勮棰樺垪琛紙鏀寔澶氶€夛級
const selectedTopics = ref([])

// 褰撳墠姝ｅ湪缂栬緫鐨勮棰樼储寮曪紙鐢ㄤ簬浠?proposal-item-detail 杩斿洖鏃舵洿鏂帮級
const currentEditingIndex = ref(-1)

// 鎴垮眿鍒楄〃鐩稿叧
const houseList = ref([])
const selectedHouseIndex = ref(0)
const housePickerIndex = ref(0)
const housePopup = ref(null)

// 鎸夊綋鍓嶅叏灞€閫変腑灏忓尯id绛涢€夋埧灞?
const filteredHouseList = computed(() => {
  if (!userStore.project) return houseList.value
  return houseList.value.filter((item) => item.complexId === userStore.project)
})

// 褰撳墠閫変腑鎴垮眿鍦板潃
const currentHouseAddress = computed(() => {
  const house = filteredHouseList.value[selectedHouseIndex.value]
  if (!house) return ''
  return `${house.complexName || ''}${house.buildingName || ''}${house.buildingName && !house.buildingName.includes('骞?) ? '骞? : ''}${house.unitName || ''}${house.houseNo || ''}`
})

// 褰撳墠閫変腑绀惧尯鍚嶇О
const currentCommunityName = computed(() => {
  // 浣跨敤鍏ㄥ眬閫変腑鐨勭ぞ鍖哄悕绉?
  return userStore.communityName || ''
})

// 鑾峰彇鎴垮眿鍒楄〃
const fetchHouseList = () => {
  getMyHousesNew({
    identityType: '1,3',
    identityStatus: '1,2',
  }).then((res) => {
    houseList.value = res.data || []
    selectedHouseIndex.value = 0
  }).catch((error) => {
    console.error('鑾峰彇鎴垮眿鍒楄〃澶辫触:', error)
  })
}

// 鎵撳紑鎴垮眿閫夋嫨鍣?
const openHousePicker = () => {
  if (filteredHouseList.value.length <= 1) return
  housePickerIndex.value = selectedHouseIndex.value
  housePopup.value?.open()
}

// 鍏抽棴鎴垮眿閫夋嫨鍣?
const closeHousePicker = () => {
  housePopup.value?.close()
}

// picker鍙樺寲
const onHousePickerChange = (e) => {
  housePickerIndex.value = e.detail.value[0]
}

// 纭閫夋嫨鎴垮眿
const confirmHousePicker = () => {
  selectedHouseIndex.value = housePickerIndex.value
  housePopup.value?.close()
}

// 鎻愪氦鎴愬姛寮圭獥
const showSuccessPopup = ref(false)

// 鎵嬫満鍙风紪杈戠浉鍏?
const isEditingPhone = ref(false)
const tempPhone = ref('')
const finalPhone = ref('') // 鏈€缁堢‘璁ょ殑鎵嬫満鍙?

// 鐐瑰嚮鎵嬫満鍙?
const handlePhoneClick = () => {
  if (isEditingPhone.value) return
  isEditingPhone.value = true
  tempPhone.value = finalPhone.value || userStore.phone || ''
}

// 淇濆瓨鎵嬫満鍙凤紙鍙繚瀛樺湪褰撳墠椤甸潰锛屼笉鏇存柊鐢ㄦ埛淇℃伅锛?
const savePhone = () => {
  // 楠岃瘉鎵嬫満鍙锋牸寮?
  const phoneReg = /^1[3-9]\d{9}$/
  if (!tempPhone.value) {
    showToast('璇疯緭鍏ユ墜鏈哄彿')
    return
  }
  if (!phoneReg.test(tempPhone.value)) {
    showToast('璇疯緭鍏ユ纭殑鎵嬫満鍙?)
    return
  }

  // 淇濆瓨鍒版渶缁堝彉閲?
  finalPhone.value = tempPhone.value
  isEditingPhone.value = false
  showToast('鎵嬫満鍙峰凡鏇存柊')
}

// 椤甸潰鍔犺浇鏃惰幏鍙栬棰樺垪琛ㄥ拰鎴垮眿鍒楄〃
onLoad(() => {
  getTopicList()
  fetchHouseList()

  // 鍦?onLoad 涓敞鍐屼簨浠剁洃鍚紝鍙敞鍐屼竴娆?
  // 鐩戝惉鍙栨秷浜嬩欢
  uni.$on('proposal-item-cancel', handleProposalItemCancel)
  // 鐩戝惉淇濆瓨浜嬩欢
  uni.$on('proposal-item-save', handleProposalItemSave)
})

// 澶勭悊鍙栨秷浜嬩欢
const handleProposalItemCancel = () => {
  currentEditingIndex.value = -1
}

// 澶勭悊淇濆瓨浜嬩欢
const handleProposalItemSave = (data) => {
  const topicData = {
    suggestTopicId: data.topicId,
    suggestTopicName: data.topicName,
    suggestTopicMatterId: data.subItem?.id,
    suggestTopicMatterName: data.subItem?.name || '',
    suggestDescription: data.description,
    fileUrl: data.attachments || '',
  }

  // 濡傛灉鏄紪杈戞ā寮忥紝鏇存柊宸插瓨鍦ㄧ殑璁
  if (currentEditingIndex.value !== -1) {
    selectedTopics.value[currentEditingIndex.value] = topicData
    currentEditingIndex.value = -1
  } else {
    // 鏂板妯″紡锛屾坊鍔犲埌鍒楄〃
    selectedTopics.value.push(topicData)
  }
}

// 椤甸潰鍗歌浇鏃剁Щ闄や簨浠剁洃鍚?
onUnload(() => {
  uni.$off('proposal-item-cancel', handleProposalItemCancel)
  uni.$off('proposal-item-save', handleProposalItemSave)
})

// 鑾峰彇鍊¤璁鍒楄〃
const getTopicList = () => {
  appSuggestListVoByCertNumber({})
    .then((res) => {
      console.log('鍊¤璁鎺ュ彛杩斿洖:', res)
      const data = res.data || res.rows || res || []
      topicList.value = Array.isArray(data)
        ? data.map((item) => ({
          value: item.suggestTopicId || item.id,
          text: item.suggestTopicName || item.name,
        }))
        : []
      console.log('澶勭悊鍚庣殑璁鍒楄〃:', topicList.value)
    })
    .catch((error) => {
      console.error('鑾峰彇鍊¤璁澶辫触:', error)
      uni.showToast({ title: '鍔犺浇璁澶辫触', icon: 'none' })
    })
}

// 鍒ゆ柇璁鏄惁宸查€変腑
const isTopicSelected = (topicId) => {
  return selectedTopics.value.some((topic) => topic.suggestTopicId === topicId)
}

// 鍒犻櫎宸查€夎棰?
const removeTopic = (index) => {
  selectedTopics.value.splice(index, 1)
}

// 閫夋嫨璁 - 璺宠浆鍒板€¤鍒嗛」椤甸潰
const selectTopic = (item) => {
  // 妫€鏌ヨ璁鏄惁宸查€変腑
  const existingIndex = selectedTopics.value.findIndex((topic) => topic.suggestTopicId === item.value)

  let url = `./proposal-item-detail?topicId=${item.value}&topicName=${encodeURIComponent(item.text)}`

  if (existingIndex !== -1) {
    // 宸查€変腑锛岃繘鍏ョ紪杈戞ā寮忥紝浼犻€掑凡濉啓鐨勬暟鎹?
    currentEditingIndex.value = existingIndex
    const topicData = selectedTopics.value[existingIndex]

    // 灏嗗凡濉啓鐨勬暟鎹紪鐮佸悗浼犻€?
    url += `&editMode=1`
    url += `&subItemId=${topicData.suggestTopicMatterId || ''}`
    url += `&subItemName=${encodeURIComponent(topicData.suggestTopicMatterName || '')}`
    url += `&description=${encodeURIComponent(topicData.suggestDescription || '')}`
    url += `&attachments=${encodeURIComponent(topicData.fileUrl || '')}`
  } else {
    // 鏈€変腑锛岃繘鍏ユ柊澧炴ā寮?
    currentEditingIndex.value = -1
    url += `&editMode=0`
  }

  // 璺宠浆鍒板€¤鍒嗛」椤甸潰
  uni.navigateTo({
    url
  })
}

// 鎻愪氦
const handleSubmit = () => {
  if (selectedTopics.value.length === 0) {
    showToast('璇疯嚦灏戦€夋嫨涓€涓€¤璁')
    return
  }

  const currentHouse = filteredHouseList.value[selectedHouseIndex.value]
  // 浣跨敤鏈€缁堢‘璁ょ殑鎵嬫満鍙凤紝濡傛灉娌℃湁淇敼鍒欎娇鐢ㄧ敤鎴?store 涓殑鎵嬫満鍙?
  const initiatorPhone = finalPhone.value || userStore.phone || ''

  const params = {
    appSuggestTopicMatterList: selectedTopics.value,
    complexId: userStore.project,
    complexCode: currentHouse?.complexCode || '',
    complexName: userStore.projectName || currentHouse?.complexName || '',
    houseId: currentHouse?.houseId || '',
    initiatorName: userStore.username || '',
    initiatorIdType: userStore.idType || '',
    initiatorIdNumber: userStore.idNumber || '',
    initiatorPhone: initiatorPhone,
    initiatorHouse: currentHouseAddress.value,
  }

  addAppSuggest(params).then((res) => {
    if (res.code == 200) {
      showSuccessPopup.value = true
    } else {
      showToast(res.msg || '鎻愪氦澶辫触')
    }
  }).catch((err) => {
    console.error('鎻愪氦鍊¤澶辫触:', err)
    showToast('鎻愪氦澶辫触锛岃绋嶅悗閲嶈瘯')
  })
}

// 纭寮圭獥 - 鍏抽棴骞惰繑鍥炲€¤鍒楄〃椤?
const handleConfirm = () => {
  showSuccessPopup.value = false
  uni.redirectTo({
    url: './list'
  })
}
</script>

