export const useVoteStore = defineStore('vote', {
  state: () => {
    return {
      signUrl: '',
      // 一般表决
      maintainChecked: '',
      maintainOptions: [],
      // 选项表决
      optionalChecked: [],
      // 排序表决
      sortResult: [],
      // 选举
      electChecked: [],
      electDetail: {},
      // 倡议
      proposeSelections: [],
      proposeSubItem: {},
      optionDetail: {},
      electRecord: {}
    }
  },
  getters: {
  },
  actions: {
    setSignUrl(url) {
      this.signUrl = url
    },
    setMaintainChecked(val) {
      this.maintainChecked = val
    },
    setMaintainOptions(arr) {
      this.maintainOptions = arr
    },
    setOptionalChecked(arr) {
      this.optionalChecked = arr
    },
    setSortResult(arr) {
      this.sortResult = arr
    },
    setElectChecked(arr) {
      this.electChecked = arr
    },
    setElectRecord(obj) {
      this.electRecord = obj
    },
    setElectDetail(obj) {
      this.electDetail = obj
    },
    setProposeSelections(arr) {
      this.proposeSelections = arr
    },
    setProposeSubItem(obj) {
      this.proposeSubItem = Object.assign({}, obj)
    },
    setOptionRecord(obj) {
      this.optionDetail = obj
    },

    clear() {
      this.signUrl = ''
      this.maintainChecked = ''
      this.maintainOptions = []
      this.optionalChecked = []
      this.sortResult = []
      this.electChecked = []
      this.proposeSelections = []
      this.proposeSubItem = {}
    }
  },
})

const voteStore = useVoteStore(store)
