import { defineStore } from 'pinia'
import { getConfigKey } from '@/api/system'
import store from '@/store/index.ts'
import fallbackMenus from '@/static/menus.fallback.json'
import { resolveStaticUrl, normalizeConfigMediaUrl } from '@/utils'

const CONFIG_KEY = 'app.suzhufang.config'
const OWNER_CARD_IMG = resolveStaticUrl('images/my/owner-card.png')
const MENU_MEDIA_KEYS = ['iconPath', 'bgPath', 'bannerImg', 'img', 'image', 'pictureUrl']

function normalizeMenuItem(item) {
  if (!item || typeof item !== 'object') return item
  const next = { ...item }
  for (const key of MENU_MEDIA_KEYS) {
    if (typeof next[key] === 'string' && next[key]) {
      next[key] = normalizeConfigMediaUrl(next[key])
    }
  }
  if (item.name === '电子业主卡') {
    const iconPath = next.iconPath || ''
    if (
      !iconPath
      || iconPath.includes('unlimited.c.')
      || iconPath.includes('zhishusz.com/zhi2-test')
    ) {
      next.iconPath = OWNER_CARD_IMG
    }
  }
  return next
}

function normalizeNavigation(navigation = {}) {
  const next = { ...navigation }
  for (const key of Object.keys(next)) {
    const sections = next[key]
    if (!Array.isArray(sections)) continue
    next[key] = sections.map((section) => {
      if (!section || typeof section !== 'object') return section
      const normalizedSection = { ...section }
      if (typeof normalizedSection.bgPath === 'string' && normalizedSection.bgPath) {
        normalizedSection.bgPath = normalizeConfigMediaUrl(normalizedSection.bgPath)
      }
      if (!section?.item?.length) return normalizedSection
      return {
        ...normalizedSection,
        item: section.item.map(normalizeMenuItem),
      }
    })
  }
  return next
}

