103: // 页面参数
104: const topicId = ref('')
105: const topicName = ref('')
106: 
107: // 议题分项列表
108: const subItemList = ref([])
109: 
110: // 选中的分项
111: const selectedSubItem = ref(null)
112: 
113: // 倡议说明
114: const description = ref('')
