119: // 计算已上传图片数量
120: const uploadedCount = computed(() => {
121:   if (!attachmentsStr.value) return 0
122:   // attachmentsStr 是逗号分隔的图片URL字符串
123:   return attachmentsStr.value.split(',').filter((url) => url.trim()).length
124: })
125: 
126: onLoad((options) => {
127:   topicId.value = options.topicId || ''
128:   topicName.value = decodeURIComponent(options.topicName || '')
129: 
130:   // 检查是否是编辑模式
131:   const isEditMode = options.editMode === '1'
132: 
133:   if (isEditMode) {
134:     // 编辑模式，反显数据
135:     const subItemId = options.subItemId || ''
136:     const subItemName = decodeURIComponent(options.subItemName || '')
137:     description.value = decodeURIComponent(options.description || '')
138:     attachmentsStr.value = decodeURIComponent(options.attachments || '')
139: 
140:     // 设置选中的分项
141:     if (subItemId) {
142:       selectedSubItem.value = {
143:         id: subItemId,
144:         name: subItemName,
145:       }
146:     }
147:   }
148: 
149:   loadSubItems()
150: })
151: 
152: // 加载议题分项数据
153: const loadSubItems = () => {
154:   listSuggestTopicMatter({
155:     suggestTopicId: topicId.value,
156:     complexId: userStore.project,
157:   }).then((res) => {
158:     const data = res.data || res.rows || []
159:     if (Array.isArray(data) && data.length) {
160:       subItemList.value = data.map((item) => ({
161:         id: item.suggestTopicMatterId || item.id,
162:         name: item.suggestTopicMatterName || item.name,
163:         ...item,
164:       }))
165: 
166:       // 如果是编辑模式，且有选中的分项，需要从列表中匹配完整的分项数据
167:       if (selectedSubItem.value && selectedSubItem.value.id) {
168:         const matchedItem = subItemList.value.find((item) => item.id === selectedSubItem.value.id)
169:         if (matchedItem) {
170:           selectedSubItem.value = matchedItem
171:         }
172:       }
173:     }
174:   }).catch((err) => {
175:     console.error('获取议题分项失败:', err)
176:   })
177: }
178: 
179: // 判断分项是否禁用
180: const isItemDisabled = (item) => {
181:   // isStart 为 '2' 或 '3' 时禁用
182:   if (item.isStart === '2' || item.isStart === '3') return true
183:   // isStart 为 '1' 且不是自己发起的，禁用
184:   if (item.isStart === '1' && !item.isMine) return true
185:   // 其他情况（isStart 为 '0' 或 isStart 为 '1' 且是自己发起的）允许选择
186:   return false
187: }
188: 
189: // 选择分项
190: const selectSubItem = (item) => {
191:   if (isItemDisabled(item)) return
192:   selectedSubItem.value = item
193: }
194: 
195: // 保存
196: const handleSave = () => {
197:   if (!selectedSubItem.value) {
198:     showToast('请选择议题分项')
199:     return
200:   }
201:   if (!description.value || !description.value.trim()) {
202:     showToast('请填写倡议说明')
203:     return
204:   }
