6:       canvas-id="zsCanvas"
7:       disable-scroll="true"
8:       @touchstart="touchstart"
9:       @touchmove="touchmove"
10:       @touchend="touchend"
11:     ></canvas>
12:   </div>
13: </template>
14: 
15: <script>
16: import { fileUpload } from "@/api/file";
17: import { showToast } from "@/utils/ui";
18: import { getSystemInfo } from "@/utils/system-info";
19: 
20: export default {
21:   name: "SignBoard",
22:   data() {
23:     return {
24:       ctx: null,
25:       previewUrl: null,
26:       points: [],
27:     };
28:   },
29:   mounted() {
30:     this.init();
31:   },
32:   methods: {
33:     touchstart(e) {
34:       let startX = e.changedTouches[0].x;
35:       let startY = e.changedTouches[0].y;
36:       let startPoint = { X: startX, Y: startY };
37:       this.points.push(startPoint);
38:       this.ctx.beginPath();
39:     },
40:     touchmove(e) {
41:       let moveX = e.changedTouches[0].x;
42:       let moveY = e.changedTouches[0].y;
43:       let movePoint = { X: moveX, Y: moveY };
44:       this.points.push(movePoint);
45:       let len = this.points.length;
46:       if (len >= 2) {
47:         this.draw();
48:       }
49:     },
50:     touchend(e) {
51:       this.points = [];
52:     },
53:     draw() {
54:       let point1 = this.points[0];
55:       let point2 = this.points[1];
56:       this.points.shift();
57:       this.ctx.lineWidth = 2;
58:       this.ctx.moveTo(point1.X, point1.Y);
59:       this.ctx.lineTo(point2.X, point2.Y);
60:       this.ctx.stroke();
61:       this.ctx.draw(true);
62:       this.getBase64();
63:     },
64:     init() {
65:       this.ctx = uni.createCanvasContext("zsCanvas", this);
66:       const fillCanvas = (width, height) => {
67:         this.ctx.fillStyle = "#fff";
68:         this.ctx.fillRect(0, 0, width, height);
69:         this.ctx.draw();
70:       };
71:       // #ifdef H5
72:       const el = document.getElementById("zsCanvas");
73:       fillCanvas(el?.scrollWidth || 300, el?.scrollHeight || 200);
74:       // #endif
75:       // #ifdef MP-WEIXIN
76:       uni
77:         .createSelectorQuery()
78:         .in(this)
79:         .select("#zsCanvas")
80:         .boundingClientRect((rect) => {
81:           fillCanvas(rect?.width || 300, rect?.height || 200);
82:         })
83:         .exec();
84:       // #endif
85:     },
86:     getBase64() {
87:       uni.canvasToTempFilePath(
88:         {
89:           canvasId: "zsCanvas",
90:           success: (res) => {
91:             // 在H5平台下，tempFilePath 为 base64
92:             // MP-WEIXIN下，tempFilePath 为 url
93:             this.previewUrl = res.tempFilePath;
94:           },
95:           fail: (err) => {},
96:         },
97:         this
98:       );
99:     },
100:     /**
101:      * base64转换为file类型
102:      * @param base64Url
103:      * @param filename
104:      * @returns
105:      */
106:     base64UrlToFile(base64Url, filename) {
107:       const arr = base64Url.split(",");
108:       if (arr.length < 2) {
109:         throw new Error("签名图片格式错误");
110:       }
111:       const mimeMatch = arr[0].match(/:(.*?);/);
112:       if (!mimeMatch) {
113:         throw new Error("签名图片格式错误");
114:       }
115:       const mime = mimeMatch[1];
116:       const bstr = atob(arr[1]);
117:       let n = bstr.length;
118:       const u8arr = new Uint8Array(n);
119:       while (n--) {
120:         u8arr[n] = bstr.charCodeAt(n);
121:       }
122:       return new File([u8arr], filename, { type: mime });
123:     },
124:     clear() {
125:       getSystemInfo({
126:         success: (res) => {
127:           let canvasW = res.windowWidth;
128:           let canvasH = res.windowHeight;
129:           this.ctx.clearRect(0, 0, canvasW, canvasH);
130:           this.ctx.draw(true);
131:           this.previewUrl = null;
132:         },
133:       });
134:     },
135:     async submit() {
136:       if (!this.previewUrl) {
137:         showToast("请签名");
138:         return;
139:       }
140:       try {
141:         // #ifdef H5
142:         const file = this.base64UrlToFile(
143:           this.previewUrl,
144:           `签名_${new Date().getTime()}.png`
145:         );
146:         const { data, code } = await fileUpload({ file });
147:         if (code == 200) {
148:           return data.fileSite;
149:         }
150:         // #endif
151: 
152:         // #ifdef MP-WEIXIN
153:         const { data: mpData, code: mpCode } = await fileUpload({
154:           filePath: this.previewUrl,
155:         });
156:         if (mpCode == 200) {
157:           return mpData.fileSite;
158:         }
159:         // #endif
160:       } catch (err) {
161:         console.error("签名上传失败", err);
162:         showToast(err?.message || "签名上传失败，请重试");
163:       }
164:     },
165:   },
166: };
