>     public List<SuggestAppVo> listByComplexIdAndStatus(AppSuggestQueryDto queryDto) {
  
          UserLoginInfo userLoginInfo = SecurityUtils.getUserLoginInfo();
          log.info("当前登录用户信息：{}", userLoginInfo);
          Map<String, String> extensions = userLoginInfo.getExtensions();
          if (CollUtil.isEmpty(extensions)) {
              return new ArrayList<>();
          }
          String idNumber = extensions.get(UserExtensionName.ID_NUMBER);
          if(StrUtil.isBlank(idNumber)){
              throw new ServiceException("获取当前登录用户证件信息失败!");
          }
         // String userName = extensions.get(UserExtensionName.REAL_NAME);
  
          if(ObjectUtil.isEmpty(queryDto.getComplexId())){
              throw new ServiceException("物业管理区域ID不能为空!");
          }
  
          LambdaQueryWrapper<Suggest> queryWrapper = new LambdaQueryWrapper<>();
          if ("0".equals(queryDto.getSuggestFlag())) {
              //我的倡议
              queryWrapper.eq(Suggest::getInitiatorIdNumber, idNumber);
          }else{
              //我的响应
              // 查询当前用户响应的倡议ID列表
              LambdaQueryWrapper<SuggestResponseRecord> responseQueryWrapper = new LambdaQueryWrapper<>();
              responseQueryWrapper.eq(SuggestResponseRecord::getResponserIdNumber, idNumber)
                      .eq(SuggestResponseRecord::getSuggestResponseStatus, DictConstant.SuggestResponseStatusType.RESPONSE)
                      //.in(SuggestResponse::getComplexId, complexIds) // 增加小区权限过滤
                      .eq(SuggestResponseRecord::getComplexId, queryDto.getComplexId())
                      .eq(SuggestResponseRecord::getTheState, DataConstants.TheState.VALID);
              List<SuggestResponseRecord> suggestResponseRecords = suggestResponseRecordService.list(responseQueryWrapper);
              if (CollectionUtils.isEmpty(suggestResponseRecords)) {
                  // 如果没有响应记录，返回空列表
                  return new ArrayList<>();
              }
              List<Long> suggestIds = suggestResponseRecords.stream()
                      .map(SuggestResponseRecord::getSuggestId)
                      .filter(Objects::nonNull)
                      .distinct()
                      .collect(Collectors.toList());



"}]

