/**
 * 业主倡议（榆林版迁移）公共工具
 */

/** 解析附件地址（支持逗号分隔字符串或数组） */
export const parseAttachments = (fileUrl) => {
  if (!fileUrl) return []
  if (typeof fileUrl === 'string') {
    return fileUrl.split(',').filter(Boolean)
  }
  if (Array.isArray(fileUrl)) {
    return fileUrl
  }
  return []
}

/** 可撤回倡议的状态：待审核(0)、响应中(3) */
export const REVOKE_ALLOW_STATUS = ['0', '3']

/**
 * 撤回倡议前置校验（与后端校验保持一致，避免用户签完字才失败）
 * @param {Object} data 倡议数据
 * @returns {string} 空字符串表示允许撤回，否则为提示文案
 */
export const checkRevokeAllowed = (data = {}) => {
  const status = String(data.suggestStatus ?? data.myState ?? '')
  if (!REVOKE_ALLOW_STATUS.includes(status)) {
    return '当前状态不允许撤回'
  }
  // 倡议创建时间（列表返回 createTime，详情返回 suggestTopicInitTime）
  const createTime = data.createTime || data.suggestTopicInitTime
  if (createTime && Date.now() - new Date(createTime).getTime() > 24 * 60 * 60 * 1000) {
    return '倡议创建已超过24小时，不允许撤回'
  }
  // 已有他人响应时不允许撤回
  if (Number(data.responseHouse || 0) > 0) {
    return '已有业主响应该倡议，不允许撤回'
  }
  // 已超过响应截止日期
  const endDate = data.suggestEndDate || data.endDate
  if (endDate && new Date(endDate).getTime() < Date.now()) {
    return '已超过响应截止日期，不允许撤回'
  }
  return ''
}

