> export function resolveStaticUrl(src, subpackage = '') {
    if (!src) return ''
    let normalized = String(src).trim().replace(/^\/+/, '')
    if (normalized.startsWith('static/')) {
      normalized = normalized.slice('static/'.length)
    }
    if (!normalized) return ''
    const staticRoot = subpackage
      ? `${String(subpackage).replace(/^\/+|\/+$/g, '')}/static`
      : 'static'
    // #ifdef H5
    const h5Base = import.meta.env.BASE_URL || '/'
    const prefix = h5Base.endsWith('/') ? h5Base : `${h5Base}/`
    return `${prefix}${staticRoot}/${normalized}`
    // #endif
    // #ifdef MP-WEIXIN
    return `${IMAGE_BASE}/${staticRoot}/${normalized}`
    // #endif
    // #ifndef H5
    // #ifndef MP-WEIXIN
    return `/${staticRoot}/${normalized}`
    // #endif
    // #endif
  }
  
  /** 将接口返回的相对资源路径转为可访问的完整 URL */
  export function resolveMediaUrl(url) {
    if (!url) return ''
    const trimmed = String(url).trim()
    if ((/^(data:|blob:)/i).test(trimmed)) return trimmed
  



